  //----
  // INDEXES
  //----
  @@unique([reset_token])
  // spellchecker: ignore-next-line
  @@index([seller_account_id, created_at], map: "mall_platform_seller_password_resets_seller_account_id_319807e6")
  @@index([expired_at])
