    searched.data.every(
      (seller) => seller.email.length > 0 && seller.id.length > 0,
    ),
  );
  TestValidator.predicate("search results preserve summary fields", () =>
    searched.data.every(
      (seller) => seller.createdAt.length > 0 && seller.updatedAt.length > 0,
    ),
  );
}

