export async function test_api_product_image_snapshot_history(
  connection: api.IConnection,
): Promise<void> {
  const sellerConnection: api.IConnection = { host: connection.host };
  const administratorConnection: api.IConnection = { host: connection.host };
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = RandomGenerator.alphaNumeric(12);
  const administratorEmail = typia.random<string & tags.Format<"email">>();
  const administratorPassword = RandomGenerator.alphaNumeric(12);
  await authorize_seller_join(sellerConnection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      href: "https://example.com/register/seller",
      referrer: "https://example.com/landing",
      ip: null,
    } satisfies IMallPlatformSeller.IJoin,
  });
  await authorize_administrator_join(administratorConnection, {
    body: {
      email: administratorEmail,
      password: administratorPassword,
    } satisfies IMallPlatformAdministrator.IJoin,
  });
  const sellerAuth = await authorize_seller_login(sellerConnection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
    } satisfies IMallPlatformSeller.ILogin,
  });
  typia.assert(sellerAuth);
  const adminAuth = await authorize_administrator_login(
    administratorConnection,
    {
      body: {
        email: administratorEmail,
        password: administratorPassword,
      } satisfies IMallPlatformAdministrator.ILogin,
    },
  );
  typia.assert(adminAuth);
  const product = await generate_random_mall_platform_seller_products_create(
    sellerConnection,
    {
      body: {
        name: RandomGenerator.name(),
        description: RandomGenerator.paragraph({ sentences: 3 }),
        categoryId: null,
        basePrice: 1000,
      } satisfies IMallPlatformProduct.ICreate,
    },
  );
  typia.assert(product);
  const page =
    await api.functional.mallPlatform.administrator.products._imageSnapshots.index(
      administratorConnection,
      {
        productId: product.id,
        body: {
          page: 1,
          pageSize: 10,
          sort: "newest",
          limit: 10,
        } satisfies IMallPlatformProductImageSnapshot.IRequest,
      },
    );
  typia.assert(page);
  TestValidator.equals("pagination current page", page.pagination.current, 1);
  TestValidator.equals("pagination limit", page.pagination.limit, 10);
  TestValidator.equals(
    "pagination records",
    page.pagination.records,
    page.data.length,
  );
  TestValidator.predicate(
    "pagination pages non-negative",
    page.pagination.pages >= 0,
  );
  TestValidator.predicate(
    "all snapshots belong to the product",
    page.data.every((row) => row.product.id === product.id),
  );
  TestValidator.predicate(
    "snapshot timestamps are valid and ordered newest first when present",
    page.data.every(
      (row, index, array) =>
        index === 0 || array[index - 1].changedAt >= row.changedAt,
    ),
  );
  const emptyProduct =
    await generate_random_mall_platform_seller_products_create(
      sellerConnection,
      {
        body: {
          name: RandomGenerator.name(),
          description: RandomGenerator.paragraph({ sentences: 2 }),
          categoryId: null,
          basePrice: 1000,
        } satisfies IMallPlatformProduct.ICreate,
      },
    );
  typia.assert(emptyProduct);
  const emptyPage =
    await api.functional.mallPlatform.administrator.products._imageSnapshots.index(
      administratorConnection,
      {
        productId: emptyProduct.id,
        body: {
          page: 1,
          pageSize: 10,
          sort: "newest",
          limit: 10,
        } satisfies IMallPlatformProductImageSnapshot.IRequest,
      },
    );
  typia.assert(emptyPage);
  TestValidator.equals(
    "empty history records",
    emptyPage.pagination.records,
    0,
  );
  TestValidator.equals("empty history pages", emptyPage.pagination.pages, 0);
  TestValidator.equals("empty history data length", emptyPage.data.length, 0);
}

