    await api.functional.mallPlatform.customer.carts.items.index(
      customerConnection,
      {
        cartId,
        body: {
          mallPlatformProductVariantId: variantBId,
          quantity: 1,
        } satisfies IMallPlatformCartItem.IRequest,
      },
