export async function test_api_cart_item_remove_own_item(
  connection: api.IConnection,
): Promise<void> {
  const ownerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(ownerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
    } satisfies IMallPlatformCustomer.IJoin,
  });
  const cart =
    await api.functional.mallPlatform.customer.carts.create(ownerConnection);
  typia.assert(cart);
  const firstItem =
    await generate_random_mall_platform_customer_carts_items_post(
      ownerConnection,
      { body: { quantity: 1 } },
    );
  typia.assert(firstItem);
  const secondItem =
    await generate_random_mall_platform_customer_carts_items_post(
      ownerConnection,
      { body: { quantity: 2 } },
    );
  typia.assert(secondItem);
  const beforeCart =
    await api.functional.mallPlatform.customer.carts.create(ownerConnection);
  typia.assert(beforeCart);
  const beforeItems: IMallPlatformCartItem.ISummary[] =
    beforeCart.cartItems ?? [];
  TestValidator.equals(
    "cart has two lines before deletion",
    beforeItems.length,
    2,
  );
  TestValidator.predicate(
    "cart contains the first item before deletion",
    beforeItems.some((item) => item.id === firstItem.id),
  );
  TestValidator.predicate(
    "cart contains the second item before deletion",
    beforeItems.some((item) => item.id === secondItem.id),
  );
  await api.functional.mallPlatform.customer.carts.items.eraseByCartidAndCartitemid(
    ownerConnection,
    {
      cartId: cart.id,
      cartItemId: firstItem.id,
    },
  );
  const afterCart =
    await api.functional.mallPlatform.customer.carts.create(ownerConnection);
  typia.assert(afterCart);
  const afterItems: IMallPlatformCartItem.ISummary[] =
    afterCart.cartItems ?? [];
  TestValidator.equals(
    "cart line count decreases by one",
    afterItems.length,
    1,
  );
  TestValidator.predicate(
    "removed item no longer exists in cart",
    !afterItems.some((item) => item.id === firstItem.id),
  );
  TestValidator.predicate(
    "remaining item still exists in cart",
    afterItems.some((item) => item.id === secondItem.id),
  );
  TestValidator.equals(
    "remaining item quantity is unchanged",
    afterItems[0].quantity,
    secondItem.quantity,
  );
  await api.functional.mallPlatform.customer.carts.items.eraseByCartidAndCartitemid(
    ownerConnection,
    {
      cartId: cart.id,
      cartItemId: secondItem.id,
    },
  );
  const emptyCart =
    await api.functional.mallPlatform.customer.carts.create(ownerConnection);
  typia.assert(emptyCart);
  const emptyItems: IMallPlatformCartItem.ISummary[] =
    emptyCart.cartItems ?? [];
  TestValidator.equals(
    "cart is empty after removing the last item",
    emptyItems.length,
    0,
  );
}

