    TestValidator.notEquals(
      "later page differs from first page when more than one page exists",
      firstPage.data,
      nextPage.data,
    );
  }
  const defaultSorted =
    await api.functional.mallPlatform.customer.wishlists.index(
      customerConnection,
      {
        body: {
          page: 1,
          limit: 10,
        } satisfies IMallPlatformWishlist.IRequest,
