export async function test_api_shipment_reject_cross_seller_items(
  connection: api.IConnection,
): Promise<void> {
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      href: "https://example.com/register",
      referrer: "https://example.com/",
    } satisfies IMallPlatformSeller.IJoin,
  });
  const shipment = await api.functional.mallPlatform.seller.shipments.create(
    sellerConnection,
    {
      body: {
        mallPlatformOrderId: typia.random<string & tags.Format<"uuid">>(),
        carrierName: RandomGenerator.name(),
        trackingNumber: RandomGenerator.alphaNumeric(12),
        trackingUrl: "https://example.com/tracking",
        shipmentItems: [
          {
            orderItemId: typia.random<string & tags.Format<"uuid">>(),
          } satisfies IMallPlatformShipmentItem.ICreate,
        ],
      } satisfies IMallPlatformShipment.ICreate,
    },
  );
  typia.assert(shipment);
  await TestValidator.error(
    "shipment item attachment should reject invalid cross-seller-style attachment",
    async () => {
      await api.functional.mallPlatform.seller.shipments.items.create(
        sellerConnection,
        {
          shipmentId: typia.random<string & tags.Format<"uuid">>(),
          body: {
            orderItemId: typia.random<string & tags.Format<"uuid">>(),
          } satisfies IMallPlatformShipmentItem.ICreate,
        },
      );
    },
  );
  TestValidator.predicate(
    "created shipment retains its original identifier and seller linkage",
    shipment.order.id !== undefined && shipment.seller.id !== undefined,
  );
}

