export async function test_api_cancellation_request_update_existing_reason(
  connection: api.IConnection,
): Promise<void> {
  const customerConnection: api.IConnection = { host: connection.host };
  const customer = await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
    } satisfies IMallPlatformCustomer.IJoin,
  });
  typia.assert(customer);
  const orderId = typia.random<string & tags.Format<"uuid">>();
  const orderItemId = typia.random<string & tags.Format<"uuid">>();
  const cancellationRequestId = typia.random<string & tags.Format<"uuid">>();
  const orderItemBefore =
    await api.functional.mallPlatform.customer.orders.items.at(
      customerConnection,
      {
        orderId,
        orderItemId,
      },
    );
  typia.assert(orderItemBefore);
  const existingRequest =
    await api.functional.mallPlatform.customer.orderItems.cancellationRequests.at(
      customerConnection,
      {
        orderItemId,
        cancellationRequestId,
      },
    );
  typia.assert(existingRequest);
  const updateBody = {
    reason: RandomGenerator.paragraph({ sentences: 2 }),
  } satisfies IMallPlatformCancellationRequest.IUpdate;
  const updatedRequest =
    await api.functional.mallPlatform.customer.orderItems.cancellationRequests.update(
      customerConnection,
      {
        orderItemId,
        body: updateBody,
      },
    );
  typia.assert(updatedRequest);
  const reloadedRequest =
    await api.functional.mallPlatform.customer.orderItems.cancellationRequests.at(
      customerConnection,
      {
        orderItemId,
        cancellationRequestId: updatedRequest.id,
      },
    );
  typia.assert(reloadedRequest);
  const orderItemAfter =
    await api.functional.mallPlatform.customer.orders.items.at(
      customerConnection,
      {
        orderId,
        orderItemId,
      },
    );
  typia.assert(orderItemAfter);
  TestValidator.equals(
    "cancellation request keeps the same id",
    updatedRequest.id,
    existingRequest.id,
  );
  TestValidator.equals(
    "updated reason is reflected in returned request",
    updatedRequest.reason,
    updateBody.reason,
  );
  TestValidator.equals(
    "reloaded request keeps updated reason",
    reloadedRequest.reason,
    updateBody.reason,
  );
  TestValidator.equals(
    "request remains linked to the same order item",
    updatedRequest.orderItem.id,
    orderItemId,
  );
  TestValidator.equals(
    "reloaded request remains linked to the same order item",
    reloadedRequest.orderItem.id,
    orderItemId,
  );
  TestValidator.equals(
    "order item itself is unchanged by request update",
    orderItemAfter.id,
    orderItemBefore.id,
  );
  TestValidator.equals(
    "order status remains unchanged",
    orderItemAfter.order.status,
    orderItemBefore.order.status,
  );
  TestValidator.equals(
    "unrelated order item state remains unchanged",
    orderItemAfter.status,
    orderItemBefore.status,
  );
}

