import { authorize_seller_refresh } from "../../../authorize/authorize_seller_refresh";

export async function test_api_refund_request_snapshot_history_listing(
  connection: api.IConnection,
): Promise<void> {
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
      href: "https://example.com/seller/join",
      referrer: "https://example.com/landing",
      ip: typia.random<string & tags.Format<"ipv4">>(),
    } satisfies IMallPlatformSeller.IJoin,
  });
  const refundRequestId = typia.random<string & tags.Format<"uuid">>();
  const firstPageRequest = {
    page: 1,
    limit: 10,
    sort: "-createdAt",
  } satisfies IMallPlatformRefundRequestSnapshot.IRequest;
  const output =
    await api.functional.mallPlatform.seller.refundRequests.snapshots.index(
      sellerConnection,
      {
        refundRequestId,
        body: firstPageRequest,
      },
    );
  typia.assert(output);
  TestValidator.equals(
    "pagination limit matches request",
    output.pagination.limit,
    firstPageRequest.limit,
  );
  TestValidator.equals(
    "pagination current matches request",
    output.pagination.current,
    firstPageRequest.page,
  );
  TestValidator.predicate(
    "pagination pages is non-negative",
    output.pagination.pages >= 0,
  );
  TestValidator.predicate(
    "snapshot data is an array",
    Array.isArray(output.data),
  );
  if (output.data.length > 0) {
    const parentRefundRequestId = output.data[0].refundRequest.id;
    for (const snapshot of output.data) {
      TestValidator.equals(
        "all snapshots belong to the same refund request",
        snapshot.refundRequest.id,
        parentRefundRequestId,
      );
    }
    for (let index = 1; index < output.data.length; index += 1) {
      const prev = output.data[index - 1];
      const curr = output.data[index];
      TestValidator.predicate(
        "snapshots are returned in reverse chronological order",
        new Date(prev.createdAt).getTime() >=
          new Date(curr.createdAt).getTime(),
      );
    }
    const laterPage = output.pagination.pages > 1 ? 2 : 1;
    const laterOutput =
      await api.functional.mallPlatform.seller.refundRequests.snapshots.index(
        sellerConnection,
        {
          refundRequestId,
          body: {
            page: laterPage,
            limit: firstPageRequest.limit,
            sort: firstPageRequest.sort,
          } satisfies IMallPlatformRefundRequestSnapshot.IRequest,
        },
      );
    typia.assert(laterOutput);
    TestValidator.equals(
      "later page keeps the same limit",
      laterOutput.pagination.limit,
      firstPageRequest.limit,
    );
    TestValidator.equals(
      "later page uses the requested page",
      laterOutput.pagination.current,
      laterPage,
    );
    if (laterOutput.data.length > 0) {
      for (const snapshot of laterOutput.data) {
        TestValidator.equals(
          "later page stays within the same refund request scope",
          snapshot.refundRequest.id,
          parentRefundRequestId,
        );
      }
    }
  }
}

