export async function test_api_review_snapshot_history_after_deletion(
  connection: api.IConnection,
): Promise<void> {
  const customerConnection: api.IConnection = { host: connection.host };
  const authorized = await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
    } satisfies IMallPlatformCustomer.IJoin,
  });
  typia.assert(authorized);
  const reviewId = typia.random<string & tags.Format<"uuid">>();
  const request: IMallPlatformReviewSnapshot.IRequest = {
    reviewId,
    page: 1,
    limit: 100,
    sort: "createdAt",
    order: "desc",
  };
  const snapshots =
    await api.functional.mallPlatform.customer.reviews.snapshots.index(
      customerConnection,
      {
        reviewId,
        body: request,
      },
    );
  typia.assert(snapshots);
  TestValidator.equals(
    "requested review id is echoed in the query",
    request.reviewId,
    reviewId,
  );
  TestValidator.equals(
    "pagination current page",
    snapshots.pagination.current,
    1,
  );
  TestValidator.equals("pagination limit", snapshots.pagination.limit, 100);
  TestValidator.predicate(
    "pagination totals are non-negative",
    snapshots.pagination.records >= 0 && snapshots.pagination.pages >= 0,
  );
  TestValidator.predicate(
    "snapshot data is an array",
    Array.isArray(snapshots.data),
  );
  if (snapshots.data.length > 0) {
    const first = snapshots.data[0];
    TestValidator.equals(
      "snapshot review id matches requested review",
      first.review.id,
      reviewId,
    );
    TestValidator.equals(
      "snapshot customer matches the authorized account",
      first.customer.id,
      authorized.id,
    );
    TestValidator.predicate(
      "snapshot timestamp is present",
      first.createdAt.length > 0,
    );
    TestValidator.predicate(
      "snapshot rating is within the review range",
      first.rating >= 1 && first.rating <= 5,
    );
  }
}

