      adminConnection,
      {
        productId,
        snapshotId,
        body,
      },
    );
  typia.assert(first);
  await api.functional.mallPlatform.administrator.products.erase(
    adminConnection,
    {
      productId,
    },
  );
  const second =
    await api.functional.mallPlatform.administrator.products.snapshots.variants.index(
      adminConnection,
      {
        productId,
        snapshotId,
        body,
      },
    );
