          },
        );
      typia.assert(output);
    },
  );
  await TestValidator.httpError(
    "non-owner seller should not access variant snapshot history",
    [401, 403, 404],
    async () => {
      const output =
        await api.functional.mallPlatform.seller.productVariants.snapshots.at(
          intruderConnection,
          {
            productVariantId: targetVariantId,
          },
        );
      typia.assert(output);
    },
  );
}

