    async () => {
      await api.functional.mallPlatform.customer.carts.items.post(
        customerConnection,
        {
          body: {
            mall_platform_product_variant_id: typia.random<
              string & tags.Format<"uuid">
            >(),
            quantity: 999999,
          } satisfies IMallPlatformCartItem.ICreate,
        },
