    }
    return acc;
  }, []);
  return {
    cart: {
      id: cartSummary.id,
      customer: cartSummary.customer,
      cartItems: items,
      totalPrice: subtotal,
      createdAt: cartSummary.createdAt,
      updatedAt: cartSummary.updatedAt,
      deletedAt: cartSummary.deletedAt,
    },
