    throw new HttpException("SKU code already exists", 409);
  }
  await MyGlobal.prisma.mall_platform_product_variants.create({
    data: await MallPlatformProductVariantCollector.collect({
      body: props.body,
      product,
    }),
  });
  return {
    status: "unavailable",
  };
}

