          rejection_reason: true,
          created_at: true,
          updated_at: true,
          deleted_at: true,
        },
      },
      order: {
        select: {
          id: true,
          order_number: true,
          status: true,
          total_amount: true,
          created_at: true,
        },
      },
    },
  });
  const total: number = await MyGlobal.prisma.mall_platform_shipments.count({
    where,
  });
  return {
    data: await ArrayUtil.asyncMap(rows, async (row) => ({
      id: row.id,
      seller: {
