  if (session === null)
    throw new HttpException("Session expired or revoked", 401);
  const customer =
    await MyGlobal.prisma.mall_platform_customers.findUniqueOrThrow({
      where: { id: decoded.id },
      select: {
        id: true,
        email: true,
        status: true,
