    new Date(
      session.expired_at.getTime() > 0
        ? session.expired_at.getTime()
        : Date.now(),
    ),
  ) as string & tags.Format<"date-time">;
  const refreshExpiresAt = toISOStringSafe(
    new Date(
      session.expired_at.getTime() > 0
        ? session.expired_at.getTime() + 7 * 24 * 60 * 60 * 1000
