}): Promise<IMallPlatformCancellationRequest> {
  const target =
    await MyGlobal.prisma.mall_platform_cancellation_requests.findFirstOrThrow({
      where: {
        id: props.cancellationRequestId,
        mall_platform_order_item_id: props.orderItemId,
