import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function patchMallPlatformCustomerPasswordResets(props: {
  customer: CustomerPayload;
  body: IMallPlatformAdministratorPasswordReset.IRequest;
}): Promise<IPageIMallPlatformAdministratorPasswordReset> {
  const page: number = props.body.page ?? 1;
  const limit: number = props.body.limit ?? 100;
  const skip: number = (page - 1) * limit;
  const resetRecord =
    await MyGlobal.prisma.mall_platform_administrator_password_resets.findFirst(
      {
        where: {
          token: props.body.token,
          deleted_at: null,
          expired_at: {
            gt: new globalThis.Date(),
          },
        },
        select: {
          id: true,
          token: true,
          expired_at: true,
          created_at: true,
          updated_at: true,
          deleted_at: true,
          administrator: {
            select: {
              id: true,
              email: true,
              grade: true,
              status: true,
              created_at: true,
              updated_at: true,
              deleted_at: true,
            },
          },
        },
      },
    );
  if (resetRecord === null) {
    throw new HttpException("Invalid or expired password reset token", 400);
  }
  await MyGlobal.prisma.mall_platform_administrators.update({
    where: { id: resetRecord.administrator.id },
    data: {
      password_hash: await PasswordUtil.hash(props.body.password),
      updated_at: new globalThis.Date(),
    },
  });
  await MyGlobal.prisma.mall_platform_administrator_password_resets.update({
    where: { id: resetRecord.id },
    data: {
      deleted_at: new globalThis.Date(),
      updated_at: new globalThis.Date(),
    },
  });
  const [data, records] = await Promise.all([
    MyGlobal.prisma.mall_platform_administrator_password_resets.findMany({
      where: { deleted_at: null },
      skip,
      take: limit,
      orderBy: { created_at: "desc" },
      select: {
        id: true,
        administrator: {
          select: {
            id: true,
            email: true,
            grade: true,
            status: true,
            created_at: true,
            updated_at: true,
            deleted_at: true,
          },
        },
        token: true,
        expired_at: true,
        created_at: true,
        updated_at: true,
        deleted_at: true,
      },
    }),
    MyGlobal.prisma.mall_platform_administrator_password_resets.count({
      where: { deleted_at: null },
    }),
  ]);
  return {
    data: data.map((item) => ({
      id: item.id,
      administrator: {
        id: item.administrator.id,
        email: item.administrator.email,
        grade: item.administrator.grade,
        status: item.administrator.status,
        createdAt: toISOStringSafe(item.administrator.created_at),
        updatedAt: toISOStringSafe(item.administrator.updated_at),
        deletedAt: item.administrator.deleted_at
          ? toISOStringSafe(item.administrator.deleted_at)
          : null,
      },
      token: item.token,
      expiredAt: toISOStringSafe(item.expired_at),
      createdAt: toISOStringSafe(item.created_at),
      updatedAt: toISOStringSafe(item.updated_at),
      deletedAt: item.deleted_at ? toISOStringSafe(item.deleted_at) : null,
    })),
    pagination: {
      current: page,
      limit,
      records,
      pages: Math.ceil(records / limit),
    },
  };
}

import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IMallPlatformCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IMallPlatformCustomer";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postMallPlatformAuthCustomerJoin(props: {
  ip: string;
  body: IMallPlatformCustomer.IJoin;
}): Promise<IMallPlatformCustomer.IAuthorized> {
  const existing = await MyGlobal.prisma.mall_platform_customers.findFirst({
    where: {
      email: props.body.email,
    },
    select: {
      id: true,
    },
  });
  if (existing !== null)
    throw new HttpException("Email already registered", 409);
  const createdAt = toISOStringSafe(new Date());
  const customerId = v4();
  const sessionId = v4();
  const accessExpiresAt = toISOStringSafe(
    new Date(Date.now() + 60 * 60 * 1000),
  );
  const refreshExpiresAt = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );
  await MyGlobal.prisma.mall_platform_customer_sessions.create({
    data: {
      id: sessionId,
      customer_id: customerId,
      ip: props.ip,
      created_at: createdAt,
      expired_at: refreshExpiresAt,
    } as any,
  });
  const customer = await MyGlobal.prisma.mall_platform_customers.create({
    data: {
      id: customerId,
      email: props.body.email,
      password_hash: await PasswordUtil.hash(props.body.password),
      status: "ACTIVE",
      created_at: createdAt,
      updated_at: createdAt,
      deleted_at: null,
    },
    select: {
      id: true,
      email: true,
      status: true,
      created_at: true,
      updated_at: true,
      deleted_at: true,
    },
  });
  const token = {
    access: jwt.sign(
      {
        type: "customer",
        id: customer.id,
        session_id: sessionId,
        created_at: createdAt,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "1h",
        issuer: "autobe",
      },
    ),
    refresh: jwt.sign(
      {
        type: "customer",
        id: customer.id,
        session_id: sessionId,
        tokenType: "refresh",
        created_at: createdAt,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      {
        expiresIn: "7d",
        issuer: "autobe",
      },
    ),
    expired_at: accessExpiresAt,
    refreshable_until: refreshExpiresAt,
  } satisfies IAuthorizationToken;
  return {
    id: customer.id,
    email: customer.email,
    status: customer.status,
    createdAt: toISOStringSafe(customer.created_at),
    updatedAt: toISOStringSafe(customer.updated_at),
    deletedAt:
      customer.deleted_at !== null && customer.deleted_at !== undefined
        ? toISOStringSafe(customer.deleted_at)
        : null,
    token,
  };
}

import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IMallPlatformSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IMallPlatformSeller";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postMallPlatformAuthSellerJoin(props: {
  ip: string;
  body: IMallPlatformSeller.IJoin;
}): Promise<IMallPlatformSeller.IAuthorized> {
  const duplicated = await MyGlobal.prisma.mall_platform_sellers.findFirst({
    where: { email: props.body.email },
    select: { id: true },
  });
  if (duplicated !== null)
    throw new HttpException("Email already registered", 409);
  const createdAt = toISOStringSafe(new Date());
  const sessionCreatedAt = createdAt;
  const sessionExpiredAt = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );
  const result = await MyGlobal.prisma.$transaction(async (prisma) => {
    const seller = await prisma.mall_platform_sellers.create({
      data: {
        id: v4(),
        email: props.body.email,
        password_hash: await PasswordUtil.hash(props.body.password),
        status: "pending",
        rejection_reason: null,
        created_at: new Date(createdAt),
        updated_at: new Date(createdAt),
        deleted_at: null,
      },
      select: {
        id: true,
        email: true,
        status: true,
        rejection_reason: true,
        created_at: true,
        updated_at: true,
        deleted_at: true,
      },
    });
    await prisma.mall_platform_seller_approval_requests.create({
      data: {
        id: v4(),
        mall_platform_seller_id: seller.id,
        status: "pending",
        rejection_reason: null,
        reviewed_at: null,
        created_at: new Date(createdAt),
        updated_at: new Date(createdAt),
        deleted_at: null,
      },
    });
    const session = await prisma.mall_platform_seller_sessions.create({
      data: {
        id: v4(),
        mall_platform_seller_id: seller.id,
        ip: props.ip,
        href: props.body.href,
        referrer: props.body.referrer,
        created_at: new Date(sessionCreatedAt),
        expired_at: new Date(sessionExpiredAt),
      },
      select: {
        id: true,
        created_at: true,
        expired_at: true,
      },
    });
    return { seller, session };
  });
  const tokenCreatedAt = toISOStringSafe(new Date());
  return {
    id: result.seller.id,
    email: result.seller.email,
    status: result.seller.status,
    rejectionReason: result.seller.rejection_reason,
    createdAt: result.seller.created_at.toISOString(),
    updatedAt: result.seller.updated_at.toISOString(),
    deletedAt:
      result.seller.deleted_at === null
        ? null
        : result.seller.deleted_at.toISOString(),
    token: {
      access: jwt.sign(
        {
          type: "seller",
          id: result.seller.id,
          session_id: result.session.id,
          created_at: tokenCreatedAt,
        },
        MyGlobal.env.JWT_SECRET_KEY,
        { expiresIn: "1h", issuer: "autobe" },
      ),
      refresh: jwt.sign(
        {
          type: "seller",
          id: result.seller.id,
          session_id: result.session.id,
          tokenType: "refresh",
          created_at: tokenCreatedAt,
        },
        MyGlobal.env.JWT_SECRET_KEY,
        { expiresIn: "7d", issuer: "autobe" },
      ),
      expired_at: result.session.expired_at.toISOString(),
      refreshable_until: sessionExpiredAt,
    },
  };
}

import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IMallPlatformSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IMallPlatformSeller";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function postMallPlatformAuthSellerLogin(props: {
  ip: string;
  body: IMallPlatformSeller.ILogin;
}): Promise<IMallPlatformSeller.IAuthorized> {
  const seller = await MyGlobal.prisma.mall_platform_sellers.findFirst({
    where: {
      email: props.body.email,
      deleted_at: null,
    },
    select: {
      id: true,
      email: true,
      status: true,
      rejection_reason: true,
      created_at: true,
      updated_at: true,
      deleted_at: true,
      password_hash: true,
    },
  });
  if (seller === null) {
    throw new HttpException("Invalid credentials", 401);
  }
  if (seller.status !== "approved") {
    throw new HttpException("Invalid credentials", 401);
  }
  if (
    (await PasswordUtil.verify(props.body.password, seller.password_hash)) ===
    false
  ) {
    throw new HttpException("Invalid credentials", 401);
  }
  const issuedAtText = new Date().toISOString();
  const issuedAtTime = new Date(issuedAtText).getTime();
  const accessExpiresAtText = new Date(
    issuedAtTime + 60 * 60 * 1000,
  ).toISOString();
  const refreshExpiresAtText = new Date(
    issuedAtTime + 7 * 24 * 60 * 60 * 1000,
  ).toISOString();
  const sessionId: string & tags.Format<"uuid"> = v4();
  await MyGlobal.prisma.mall_platform_seller_sessions.create({
    data: {
      id: sessionId,
      mall_platform_seller_id: seller.id,
      ip: props.ip,
      href: "",
      referrer: "",
      created_at: issuedAtText,
      expired_at: refreshExpiresAtText,
