          administrator_id: props.administrator.id,
          status: {
            notIn: ["approved", "rejected"],
          },
        },
        select: {
          id: true,
        },
      },
    );
  if (existing !== null) {
    throw new HttpException("Duplicate administrator approval request", 409);
