import { TypedBody, TypedRoute } from "@nestia/core";
import { Controller, Ip } from "@nestjs/common";
import typia from "typia";

import { IMallPlatformCustomer } from "../../../../api/structures/IMallPlatformCustomer";
import { postMallPlatformAuthCustomerJoin } from "../../../../providers/postMallPlatformAuthCustomerJoin";
import { postMallPlatformAuthCustomerLogin } from "../../../../providers/postMallPlatformAuthCustomerLogin";
import { postMallPlatformAuthCustomerRefresh } from "../../../../providers/postMallPlatformAuthCustomerRefresh";

@Controller("/mallPlatform/auth/customer")
export class MallplatformAuthCustomerController {
  /**
   * Register a new customer account using email and password credentials. This operation creates the authenticated shopper identity that is required before any marketplace features can be used.
   *
   * The customer actor is the member-level shopper account in the platform, so this endpoint starts the lifecycle for an account that will later own shopping carts, shipping addresses, orders, wishlists, and reviews. The response returns the authorized token payload after successful registration.
   *
   * If the email is already registered or the input fails validation, the request must be rejected with a clear client error. The endpoint should remain limited to authentication setup and should not expose any profile, order, or browsing data.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Customer registration request containing email and password credentials.
   * @x-autobe-authorization-type join
   * @x-autobe-authorization-actor customer
   * @x-autobe-specification Validate the customer's registration payload, ensure the email is unique, create the customer account, initialize any required linked customer profile/session state, and issue JWT tokens on success. Reject duplicate email addresses and invalid credentials with appropriate 4xx responses. The operation must not create any public profile or domain records beyond what account registration requires.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("join")
  public async join(
    @Ip()
    ip: string,
    @TypedBody()
    body: IMallPlatformCustomer.IJoin,
  ): Promise<IMallPlatformCustomer.IAuthorized> {
    try {
      return await postMallPlatformAuthCustomerJoin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Authenticate an existing customer account with email and password credentials. Customers must be able to sign in before using any shopper-facing features on the platform.
   *
   * This endpoint is the login entry point for the customer actor, which represents the authenticated shopper account. On success it returns the authorized token payload used for subsequent API access.
   *
   * If the credentials are invalid or the account is not allowed to sign in, the request must be rejected. The response should not leak whether the email is registered, and it must remain strictly limited to authentication results.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Customer login request containing email and password credentials.
   * @x-autobe-authorization-type login
   * @x-autobe-authorization-actor customer
   * @x-autobe-specification Validate the customer's email and password against the customer account store, enforce account status restrictions such as banned or otherwise blocked states, and issue new JWT tokens on success. Do not return sensitive credential material. Failed authentication must return a generic unauthorized error without revealing whether the email exists.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("login")
  public async login(
    @Ip()
    ip: string,
    @TypedBody()
    body: IMallPlatformCustomer.ILogin,
  ): Promise<IMallPlatformCustomer.IAuthorized> {
    try {
      return await postMallPlatformAuthCustomerLogin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Refresh the authenticated customer session using the current refresh credential. This operation supports the platform's JWT-based authentication flow by extending the customer's ability to access protected shopper features without requiring a full login each time.
   *
   * The customer actor is the registered shopper account, and this endpoint is used only to renew authentication tokens. It does not expose customer profile data or modify marketplace resources.
   *
   * If the refresh credential is invalid or expired, the request must fail with an authentication error so the client can send the user back to the login flow.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Customer token refresh request containing the current refresh credential.
   * @x-autobe-authorization-type refresh
   * @x-autobe-authorization-actor customer
   * @x-autobe-specification Accept a refresh token or equivalent refresh credential, verify its validity and expiration, rotate or reissue token state as required by the JWT strategy, and return a fresh authorized token set. Reject expired, revoked, malformed, or otherwise invalid refresh credentials with an unauthorized response.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("refresh")
  public async refresh(
    @TypedBody()
    body: IMallPlatformCustomer.IRefresh,
  ): Promise<IMallPlatformCustomer.IAuthorized> {
    try {
      return await postMallPlatformAuthCustomerRefresh({
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

