  ): Promise<IMallPlatformProductVariant> {
    try {
      return await getMallPlatformSellerProductVariantsProductVariantIdAvailability(
        {
          seller,
          productVariantId,
        },
      );
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

